import{_ as t,o,c as a,a5 as r}from"./chunks/framework.DJo0M80U.js";const u=JSON.parse('{"title":"HJ108 求最小公倍数","description":"描述 正整数A和正整数B 的最小公倍数是指 能被A和B整除的最小的正整数值，设计一个算法，求输入A和B的最小公倍数。 数据范围： 输入描述： 输入两个正整数A和B。 输出描述： 输出A和B的最小公倍数。 示例1 输入： 5 7 复制 输出： 35 复制 示例2 输入： 2 4 复。","frontmatter":{"title":"HJ108 求最小公倍数","date":"2026-08-11T00:00:00.000Z","categories":["前端面试与实战"],"tags":["前端面试","算法","求职","教程","OneNote","算法训练"],"description":"描述 正整数A和正整数B 的最小公倍数是指 能被A和B整除的最小的正整数值，设计一个算法，求输入A和B的最小公倍数。 数据范围： 输入描述： 输入两个正整数A和B。 输出描述： 输出A和B的最小公倍数。 示例1 输入： 5 7 复制 输出： 35 复制 示例2 输入： 2 4 复。","sidebarWeight":53,"lastUpdated":false,"feed":false,"source":"onenote","sourceNote":"OneNote/a-吊打面试官/算法题/华为简单[31个]/HJ108 求最小公倍数.md"},"headers":[],"relativePath":"posts/前端面试与实战/03-算法训练/华为简单[31个]/HJ108 求最小公倍数.md","filePath":"posts/前端面试与实战/03-算法训练/华为简单[31个]/HJ108 求最小公倍数.md"}'),s={name:"posts/前端面试与实战/03-算法训练/华为简单[31个]/HJ108 求最小公倍数.md"};function c(n,e,d,p,i,l){return o(),a("div",null,[...e[0]||(e[0]=[r('<div><h1 id="hj108-求最小公倍数" tabindex="-1">HJ108 求最小公倍数 <a class="header-anchor" href="#hj108-求最小公倍数" aria-label="Permalink to &quot;HJ108 求最小公倍数&quot;">​</a></h1><blockquote><p>本节目标：理解“HJ108 求最小公倍数”的核心思路，并能把它用于实际开发或面试表达。</p></blockquote><blockquote><p>说明：原 OneNote 中有图片引用，但图片未包含在导出目录中；本页保留了可用的文字与代码内容。 <strong>描述</strong> 正整数A和正整数B 的最小公倍数是指 能被A和B整除的最小的正整数值，设计一个算法，求输入A和B的最小公倍数。 数据范围：</p></blockquote><p><strong>输入描述：</strong> 输入两个正整数A和B。 <strong>输出描述：</strong> 输出A和B的最小公倍数。 <strong>示例1</strong> 输入： 5 7 ==复制== 输出： 35 ==复制== <strong>示例2</strong> 输入： 2 4 ==复制== 输出： 4</p><p>要计算两个正整数A和B的最小公倍数（LCM），一种有效的方法是先计算它们的最大公约数（GCD），然后使用这个公式：</p><p>这个公式的原理基于这样一个事实：两个数的乘积等于它们的最小公倍数和最大公约数的乘积。</p><p>def lcm(a, b): &quot;&quot;&quot;计算最小公倍数（LCM）&quot;&quot;&quot; return a * b // gcd(a, b)</p><h1 id="输入" tabindex="-1">输入 <a class="header-anchor" href="#输入" aria-label="Permalink to &quot;输入&quot;">​</a></h1><p>a, b = map(int, input().split())</p><h1 id="计算并输出最小公倍数" tabindex="-1">计算并输出最小公倍数 <a class="header-anchor" href="#计算并输出最小公倍数" aria-label="Permalink to &quot;计算并输出最小公倍数&quot;">​</a></h1><p>print(lcm(a, b))</p><p>这段代码首先定义了一个<code>gcd</code>函数，用于计算两个数的最大公约数，采用的是欧几里得算法。然后，<code>lcm</code>函数使用最大公约数来计算最小公倍数，并返回结果。最后，代码读取输入，调用<code>lcm</code>函数，并输出结果。</p><p>这个<code>gcd</code>函数是使用欧几里得算法（Euclidean algorithm）来计算两个正整数<code>a</code>和<code>b</code>的最大公约数（Greatest Common Divisor, GCD）。欧几里得算法是一种非常高效的算法，用于找出两个数的最大公约数，也就是能够同时整除它们的最大的数。</p></div>',1)])])}const h=t(s,[["render",c]]);export{u as __pageData,h as default};
